// what makes one engine different from another: its specs, gearing, mesh, labels and test targets.
// Each engine lives in engines/<type>/, fills one engineType and registers it with REGISTER_ENGINE
// (below); engines/all.hpp, generated by the Makefile from the engines' engine.mk fragments, includes
// every engine header.
#pragma once
#include "physics.hpp"
#include "exhaust.hpp"

// what the superbike physics test expects from an engine (published figures, with tolerance)
struct bikeSpec {
    const char *name;
    double dispLo, dispHi;
    double limLo, limHi;                   // peak rpm bouncing on the limiter
    const char *torqueWhat, *torqueRpmWhat, *powerWhat, *powerRpmWhat;
    double torqueLo, torqueHi, torqueRpmLo, torqueRpmHi;
    double powerLo, powerHi, powerRpmLo, powerRpmHi;
    double sweepTo;                        // dyno sweep top, rpm
    std::vector<double> pattern;           // firing intervals, deg, one per cylinder (they add up to 720)
    const char *patternWhat;
    const char *bikeWhat;
    double upshiftLo, upshiftHi;           // rpm at the 1 -> 2 upshift, full throttle
    const char *topWhat;
    double topLo, topHi;
    double neutralSettle;                  // s for the revs to fall back to idle after N at speed
    double takeoffMinRpm = 900.0;          // lowest rpm in the gentle (25%) manual take-off

    // The rest have defaults for a 1000 cc superbike (idle ~1250 rpm, limiter ~14000+, 6 gears): an
    // engine that idles, revs or launches differently sets its own.
    // on the stand
    double crankLo = 200.0, crankHi = 500.0;           // cranking speed with the ignition off, mean rpm
    double catchRpm = 800.0;                           // it has caught once the starter gets it past this
    double flareLo = 1300.0, flareHi = 3500.0;         // start flare, peak rpm
    double idleLo = 1150.0, idleHi = 1350.0;           // idle speed, mean rpm
    double idleMapLo = 25.0, idleMapHi = 60.0;         // idle manifold pressure, kPa
    double toLimiterLo = 0.25, toLimiterHi = 1.5;      // s from idle to the limiter, full throttle in neutral
    double closedLo = 1100.0, closedHi = 1500.0;       // rpm 4 s after snapping the throttle shut
    double coastFromRpm = 8000.0;                      // coast-down (ignition off) starts here
    double shakeRpm = 10000.0;                         // the balance check runs at this locked speed
    double shakeMax1st = 0.0;                          // N, most 1st-order vertical force there; 0: 5% of
                                                       // half the pistons moving together without counterweights
    double firingRpm = 3000.0;                         // the firing-interval check runs at this locked speed
    // on the bike
    double idleGearLo = 1100.0, idleGearHi = 1450.0;   // idling in 1st (automatic), rpm
    const char *zeroTo100What = "0-100 km/h, full throttle (tests ~3.0-3.4 s)";
    double zeroTo100Lo = 2.6, zeroTo100Hi = 3.7;       // s
    const char *zeroTo200What = "0-200 km/h (road tests ~5.5-7 s)";
    double zeroTo200Lo = 5.0, zeroTo200Hi = 8.0;       // s (zeroTo200What nullptr: no check, for a bike that
                                                       // never gets there)
    double launchAccelLo = 0.8, launchAccelHi = 1.15;  // peak smoothed acceleration with wheelie control, g
    double shiftRpm = 11000.0;                         // manual tests: quickshift up at this rpm (70-80% pedal)
    double shiftRpmGentle = 10000.0;                   // ... and at this one (50% pedal, up to 4th)
                                                       // (both must be below the rev limiter)
    bool stallsOnClutchDump = true;                    // dumping the clutch in 1st at idle stalls it (a light
                                                       // crank); false: it must pull away without a lurch
    double dumpMinRpm = 0.0;                           // ... and without falling below this, rpm (0: half idleLo)
    double neutralRevMin = 8000.0;                     // revving in N at 40% pedal reaches at least this
    double neutralIdleLo = 1000.0, neutralIdleHi = 2200.0;  // rpm after coasting in N from speed
    double rejoinLo = 3000.0, rejoinHi = 14000.0;      // rpm once N picks a gear again at speed
    bool liftsFront = true;                            // strong enough to wheelie: the wheelie control must
                                                       // cut in, and with it off the launch passes 1.15 g
    double downshiftMaxMs = 200.0;                     // a rev-matched quickshift down takes at most this
};

// what the car physics test (physicsTestCar, src/test_car.hpp) expects from a car (published figures,
// with tolerance). The engine's balance and firing order are checked against its own geometry, so
// they need no targets; the turbo checks run for an engine with its boost always on.
struct rpmTarget {
    double rpm, lo, hi;                    // the WOT dyno at rpm (a multiple of 500) must read lo .. hi
};
struct carSpec {
    const char *name = "";
    double dispLo = 0.0, dispHi = 0.0;     // cc
    // on the stand, in neutral
    double crankLo = 150.0, crankHi = 350.0;     // cranking speed with the ignition off, mean rpm
    double flareLo = 850.0, flareHi = 2000.0;    // start flare, peak rpm
    double idleLo = 750.0, idleHi = 850.0;       // idle speed, mean rpm
    double idleMapLo = 20.0, idleMapHi = 50.0;   // idle manifold pressure, kPa
    double toLimiterLo = 0.5, toLimiterHi = 2.5; // s from idle to the limiter, full throttle
    double limiterOver = 400.0;                  // peak rpm on the limiter: revLimit .. revLimit + this
    double liftLo = 700.0, liftHi = 950.0;       // rpm 4 s after lifting off the limiter
    // WOT dyno, speed locked, from 1000 rpm in 500 rpm steps
    double sweepTo = 7000.0;
    const char *torqueWhat = "peak torque";
    double torqueLo = 0.0, torqueHi = 0.0;       // N m
    double torqueRpmLo = 0.0, torqueRpmHi = 0.0;
    const char *powerWhat = "peak power";
    double powerLo = 0.0, powerHi = 0.0;         // kW
    double powerRpmLo = 0.0, powerRpmHi = 0.0;
    std::vector<rpmTarget> torqueAt, powerAt;    // more points on the curves (N m, kW)
    double plateauFrom = 0.0, plateauTo = 0.0, plateauMax = 0.0;  // torque max - min over this range (0: none)
    // a boosted engine (engineType::boost): turbo checks
    double cylMaxLo = 80.0, cylMaxHi = 150.0;    // highest cylinder pressure on the dyno, bar
    double turboMaxLo = 80.0, turboMaxHi = 180.0;  // highest shaft speed on the dyno, krpm
    double spoolRpm = 2500.0;                    // floored from part pedal at this held speed...
    double spoolLo = 0.3, spoolHi = 2.5;         // ... s to 90% of the boost target
    // the car
    const char *carWhat = "";                    // headline for the car section
    const char *zeroTo100What = "0-100 km/h at full throttle";
    double zeroTo100Lo = 0.0, zeroTo100Hi = 0.0;  // s
    const char *zeroTo200What = nullptr;         // nullptr: no 0-200 check
    double zeroTo200Lo = 0.0, zeroTo200Hi = 0.0;
    double launchLo = 0.0, launchHi = 0.0;       // peak rpm in the first 0.6 s of a WOT launch (0: no check)
    // launch control: brake and full throttle held 2 s at a standstill (the car must stay put, the revs
    // held), then the brake released: 0-100 km/h from the release. nullptr: no check
    const char *launchTo100What = nullptr;
    double launchTo100Lo = 0.0, launchTo100Hi = 0.0;  // s
    double wotUpLo = 0.0;                        // lowest WOT upshift rpm (at most the limiter + 100)
    double lightUpLo = 2000.0, lightUpHi = 3500.0;  // first upshift at 20% pedal, rpm
    double hillPedal = 0.35, hillGrade = 0.12;   // cruise at this pedal 15 s, then this grade...
    int flatGearLo = 3, flatGearHi = 5;          // ... the gear it cruises in on the flat
    double coastDownLo = 0.0, coastDownHi = 0.0;  // normal mode, coasting: first downshift rpm (0: no check)
    bool dumpStalls = true;                      // manual: dumping the clutch at idle in 1st stalls it
    double reverseLo = -40.0, reverseHi = -5.0;  // km/h after 4 s in R at 25% pedal
};

struct engineType;
int physicsTestCar(const engineModel &e, const engineType &t);  // src/test_car.hpp

// one step of a scripted ride for --wav (bikes): hold these controls until `until` seconds
struct rideStep {
    double until;
    bool starter;
    double throttle;
    int shift;                             // +1 into gear from N, -1 quickshift down (rider takes over)
    const char *what;
    bool brake = false;
};

struct engineType;

enum class builtInBoost { none, turbo, supercharger };
const char *boostName(builtInBoost b) {
    return b == builtInBoost::turbo ? "turbo" : b == builtInBoost::supercharger ? "supercharger" : "none";
}
int physicsTestBike(const engineModel &e, const engineType &t);  // src/test_bike.hpp

// another version of an engine (--variant name): a whole engineType of its own (params, test targets,
// labels) that shares the engine's mesh
struct engineVariant {
    const char *name;                      // --variant value (--tuned yes is --variant tuned)
    const engineType &(*type)();
};

struct engineType {
    const char *id = "";                   // --engine-type value
    const char *aliases = "";              // other accepted names, space separated
    const char *name = "";                 // short name for tests and messages
    const char *summary = "";              // one line for --engine-type list
    const char *label = "";                // HUD: what is running
    const char *firingLabel = "";          // HUD: a descriptive firing order (e.g. "Twin Pulse 0-90-290-380");
                                           // empty: the order from the mesh's lags (firingOrder, "1-2-4-3")
    const char *windowTitle = "";
    const char *hudTag = "";               // shown after the rpm on the riding HUD (e.g. TUNED)
    const char *credit = "";               // model licence line (CC-BY needs it on screen)
    const char *meshFile = "";             // relative to the project root
    const char *buildHint = "";            // how to make the mesh when it is missing
    bool bike = false;                     // bike drivetrain, bike gearbox, superbike tests
    // the boost the engine is built with, always on (the H2's supercharger, the RS 3's turbo): its
    // exhaust() places turboMeshFile, drawn and spun like --turbo yes. It must agree with
    // engine().turbo.supercharger (setupSim checks). none: --turbo yes may still fit one (exhaustTurbo)
    builtInBoost boost = builtInBoost::none;
    engineParams (*engine)() = nullptr;    // engine physics and sound
    drivetrainParams (*drive)() = nullptr; // clutch, gearbox and vehicle
    int (*physTest)(const engineModel &, const engineType &) = nullptr;  // --phystest
    int (*physTestTurbo)(const engineModel &, const engineType &) = nullptr;  // --turbo yes --phystest
    bikeSpec (*spec)() = nullptr;          // bikes: --phystest targets
    carSpec (*car)() = nullptr;            // cars on physicsTestCar: --phystest targets
    // bike gearbox drawing (src/bike_gearbox.hpp): which side of the crank the box goes (+1 toward +x,
    // -1 toward -x) and the primary gear module. Where the crank's primary gear sits along the crank
    // comes from the mesh (zPrimary, see primaryGearZ)
    float gearboxSide = 1.f, primaryModule = 2.6f;
    // the exhaust system (src/exhaust.hpp): headers from the ports to the tailpipe, in mesh space
    exhaustLayout (*exhaust)(const engineModel &) = nullptr;
    // --turbo yes: the exhaust with a turbocharger in it (its turboSpec places src/turbo.hpp's model)
    exhaustLayout (*exhaustTurbo)(const engineModel &) = nullptr;
    const char *turboMeshFile = "";        // relative to the project root
    const char *turboFallbackMeshFile = "";  // drawn when turboMeshFile cannot be loaded (the RS 3's procedural
                                           // turbo, in place of the optional downloaded model); "": none
    const char *turboBuildHint = "";
    const char *turboCredit = "";          // --turbo yes: the turbo model's licence line, under credit
    bool hudFiringLine = true;             // the HUD names the firing order above the cylinders' strokes
    std::vector<rideStep> ride;            // bikes: the --wav demo ride (empty: the stand script)
    std::vector<engineVariant> variants;   // other versions of this engine (--variant name)
};

// the variant of t called name; nullptr when it has none
const engineType *findVariant(const engineType &t, const std::string &name) {
    for (const engineVariant &v : t.variants)
        if (name == v.name) return &v.type();
    return nullptr;
}

// ---- the engine registry ----------------------------------------------------------------------
// Each engine's header ends with REGISTER_ENGINE(itsTypeFunction, key). --engine-type list (and every
// listing) shows the engines in key order, so it stays stable whatever order the headers are included
// in: inline4 10, v4 20, s1000rr 30, h2 40; a new engine picks a free key. A type function must not
// look other engines up (findEngineType) while it builds its engineType: the registry calls it while
// it is itself being built (libc++ stops with "recursive initialization"). Looking up inside a
// function the engineType points to (engine, drive...) is fine: those run later.
struct engineRegistration {
    const engineType &(*type)();
    int key;
};
inline std::vector<engineRegistration> &engineRegistry() {
    static std::vector<engineRegistration> r;
    return r;
}
inline bool registerEngine(const engineType &(*type)(), int key) {
    engineRegistry().push_back({type, key});
    return true;
}
#define REGISTER_ENGINE(fn, key) inline const bool engineRegistered_##fn = registerEngine(&fn, key)

// the firing order the HUD shows: the engine's label, or the order from the mesh
std::string hudFiring(const engineType &t, const engineModel &e) { return *t.firingLabel ? t.firingLabel : firingOrder(e); }
